INSERT INTO questions_entretien (id,candidat_id,questions_json,posees_json,coche_par_json,updated_at) VALUES (11,11,'["Quels logiciels de conception architecturale maîtrisez-vous, et pouvez-vous décrire un projet sur lequel vous les avez utilisés concrètement ?", "Comment lisez-vous et interprétez-vous un plan d''exécution architectural, et quels éléments vérifiez-vous en priorité sur un chantier de suivi ?", "Quelle est la différence entre un permis de construire et une autorisation de lotir, et quelles pièces constituent un dossier de demande de permis de construire au Maroc ?", "Votre formation est en Marketing et Commerce International, ce qui est éloigné de l''architecture — qu''est-ce qui vous a conduit vers ce poste et quelles compétences avez-vous développées pour combler cet écart ?", "Durant vos 5 années d''expérience, avez-vous été impliqué dans des projets liés à la construction, à l''urbanisme ou à l''aménagement du territoire, même indirectement ?", "Pouvez-vous citer une situation professionnelle où vous avez dû coordonner plusieurs intervenants sur un projet complexe, et quel a été votre rôle précis ?", "Pourquoi postulez-vous à un poste d''Assistant Architecte alors que votre parcours académique et professionnel ne s''y rattache pas directement, et quel plan avez-vous pour acquérir les compétences manquantes ?", "Où vous voyez-vous professionnellement dans 3 à 5 ans, et en quoi ce poste à l''ADER s''inscrit-il dans cette trajectoire ?", "Que savez-vous des missions de l''Agence de Développement Régional de Fès-Meknès, et quels projets structurants menés par l''ADER avez-vous identifiés avant cet entretien ?", "Le secteur public impose des contraintes spécifiques — délais réglementaires, marchés publics, reddition de comptes — comment vous y préparez-vous et en quoi cela diffère-t-il de votre expérience actuelle ?"]','[]','{}','2026-08-27 13:27:41.062883') ON CONFLICT (id) DO NOTHING;